const P=window.People,$=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>n==null?'—':Number(n).toLocaleString('ko-KR',{maximumFractionDigits:1});const won=n=>n==null?'—':fmt(Math.round(n/10000));const pct=(n,d)=>d?fmt(n/d*100)+'%':'—';
const TODAY_KR=new Date().toLocaleDateString('sv-SE',{timeZone:'Asia/Seoul'});const COMPARISON_DATE=TODAY_KR.slice(5,7)>='07'?TODAY_KR.slice(0,4)+'-06-30':(Number(TODAY_KR.slice(0,4))-1)+'-12-31';
let state={tab:'overview',company:'전체',current:[],previous:[],demo:false,currentLoaded:false,previousLoaded:false,currentFile:'',previousFile:'',date:TODAY_KR,prevDate:COMPARISON_DATE,error:'',warnings:'',suppress:false,benchmark:'organization'};
function sample(){const raw=[];for(let i=1;i<=124;i++){let company=i<=86?'플랜티넷':'플랜티엠',n=i<=86?i:i-86;const rank=['사원','사원','대리','대리','과장','차장','부장','임원'][i%8],join=i>112?`2026-0${7+i%3}-0${1+i%8}`:`${2011+i%15}-${String(1+i%12).padStart(2,'0')}-15`;raw.push({'회사':company,'사번':`${company==='플랜티넷'?'PN':'PM'}${String(n).padStart(3,'0')}`,'이름':`가상직원${i}`,'생년월일':`${1969+i%33}-${String(1+i%12).padStart(2,'0')}-10`,'성별':i%3===0?'여':'남','입사일':join,'퇴사일':i>120?'2026-08-15':'','근무부서':['경영지원','기술개발','사업운영','영업'][i%4],'직군':['경영지원','연구개발','기술운영','영업·사업'][i%4],'직급':rank,'고용형태':i%12===0?'계약직':'정규직','연봉':({사원:3800,대리:4700,과장:5700,차장:6700,부장:7900,임원:11000}[rank]+i%7*120)*10000});}const rows=P.normalize(raw).rows;state.current=rows;state.previous=rows.filter(r=>r.join<='2026-06-30').map(r=>({...r,leave:null,salary:Math.round(r.salary/1.04)}));}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',4200);}
function data(){const cur=P.active(state.current,state.date,state.company),prev=P.active(state.previous,state.prevDate,state.company);return {cur,prev,s:P.summary(cur,state.date),p:P.summary(prev,state.prevDate)};}
const signed=n=>(n>0?'+':'')+fmt(n);function delta(a,b,unit='명'){if(!state.previousLoaded)return '<span class="delta">비교자료를 업로드해 주세요</span>';const d=a-b;return `<span class="chip ${d<0?'down':''}">${signed(d)}${unit}</span><span class="delta">이전 기준일 대비 ${b?pct(d,b):'비교 불가 (이전 0)'}</span>`;}
function head(title,sub,tag=''){return `<div class="panelhead"><div><h2>${title}</h2><p>${sub}</p></div>${tag?`<span class="tag">${tag}</span>`:''}</div>`;}
function masked(n){return state.suppress&&n>0&&n<5?'5명 미만':fmt(n)+'명';}
function bars(items,total){if(!total)return '<div class="empty">집계할 재직자가 없습니다.</div>';const max=Math.max(...items.map(x=>x.count),1);return `<div class="horizontal">${items.map(x=>`<div class="barrow"><span>${esc(x.label)}</span><div class="track"><div class="fill" style="width:${state.suppress&&x.count>0&&x.count<5?0:x.count/max*100}%"></div></div><span class="barvalue">${masked(x.count)} <small>${state.suppress&&x.count>0&&x.count<5?'':pct(x.count,total)}</small></span></div>`).join('')}</div>`;}
function kpis(d){return `<div class="kpis"><div class="card dark"><div class="klabel">전체 재직 인원 <span class="kicon">◫</span></div><div class="number">${fmt(d.s.count)}<small>명</small></div>${delta(d.s.count,d.p.count)}</div><div class="card"><div class="klabel">연봉 합계 <span class="kicon">₩</span></div><div class="number">${d.s.paid?fmt(d.s.total/100000000):'—'}<small>억 원</small></div><div class="delta">연봉 입력 ${d.s.paid} / ${d.s.count}명 · 계약연봉 합계</div></div><div class="card"><div class="klabel">평균 연봉 <span class="kicon">↗</span></div><div class="number">${won(d.s.average)}<small>만 원</small></div><div class="delta">중앙값 ${won(d.s.median)}만 원 · 입력자 기준</div></div><div class="card"><div class="klabel">평균 연령 <span class="kicon">◷</span></div><div class="number">${fmt(d.s.age)}<small>세</small></div><div class="delta">만 나이 · 생년월일 입력 ${d.s.ageN}명</div></div></div>`;}
function companyPanel(){const rows=(state.company==='전체'?P.companies:[state.company]).map(c=>{const a=P.active(state.current,state.date,c),b=P.active(state.previous,state.prevDate,c),s=P.summary(a,state.date);return `<tr><td class="companyname"><span class="dot ${c==='플랜티엠'?'second':''}"></span>${c}</td><td>${masked(a.length)}</td><td>${state.previousLoaded?masked(b.length):'—'}</td><td class="change">${state.previousLoaded?`<button class="change-detail" data-change-company="${c}" aria-label="${c} 인원 변동 상세 보기">${signed(a.length-b.length)} <span>상세 ↗</span></button>`:'—'}</td><td>${state.suppress&&a.length>0&&a.length<5?'—':won(s.average)}</td></tr>`;}).join('');return `<section class="panel">${head('회사별 인원 현황','선택한 회사의 재직 인원과 비교일자 대비 변화',state.company==='전체'?'그룹 전체':state.company)}<div class="tablewrap"><table><thead><tr><th>회사</th><th>현재 인원</th><th>이전 인원</th><th>증감 (명)</th><th>평균 연봉 (만원)</th></tr></thead><tbody>${rows}</tbody></table></div></section>`;}
function tenurePanel(d){return `<section class="panel">${head('근속구간별 인원현황','입사일과 보고 기준일 사이의 근속 기간','5개 구간')}${bars(P.distribution(d.cur,state.date,'tenure'),d.cur.length)}</section>`;}
function agePanel(d){return `<section class="panel">${head('연령별 인원현황','보고 기준일의 만 나이 기준')}${bars(P.distribution(d.cur,state.date,'age'),d.cur.length)}</section>`;}
function genderPanel(d){const groups=['남성','여성','미입력/기타'].map(label=>({label,count:d.cur.filter(r=>r.gender===label).length})),colors=['#087e7d','#a1b9c8','#e5eaed'];let a=0;const stops=groups.map((x,i)=>{const b=a;a+=d.cur.length?x.count/d.cur.length*100:0;return `${colors[i]} ${b}% ${a}%`;}).join(',');return `<section class="panel">${head('성별 인원현황','미입력·기타 성별을 포함한 전체 재직자 기준')}<div class="gender">${state.suppress?'<div class="mini">소규모 집단 보호 적용</div>':`<div class="donut" style="background:${d.cur.length?'conic-gradient('+stops+')':'#edf2f3'}"><div class="donutcenter">${fmt(d.cur.length)}<small>TOTAL PEOPLE</small></div></div>`}<div class="genderstats">${groups.map((g,i)=>`<div><span><span class="dot" style="background:${colors[i]}"></span>${g.label}</span><span><b>${masked(g.count)}</b> <small>${state.suppress&&g.count>0&&g.count<5?'':pct(g.count,d.cur.length)}</small></span></div>`).join('')}</div></div></section>`;}
function rankTable(d){const ranks=P.ranks(d.cur,state.date);return `<div class="tablewrap"><table><thead><tr><th>직급</th><th>인원</th><th>연봉 입력</th><th>평균 연봉 (만원)</th><th>중앙값 (만원)</th><th>연봉 합계 (만원)</th><th>연봉 비중</th></tr></thead><tbody>${ranks.length?ranks.map(r=>{const hide=state.suppress&&r.count<5;return `<tr><td class="companyname">${esc(r.rank)}</td><td>${masked(r.count)}</td><td>${hide?'—':r.paid+'명'}</td><td>${hide?'—':won(r.average)}</td><td>${hide?'—':won(r.median)}</td><td>${hide||!r.paid?'—':won(r.total)}</td><td>${hide||!r.paid?'—':pct(r.total,d.s.total)}</td></tr>`;}).join(''):'<tr><td colspan="7" class="empty">집계할 자료가 없습니다.</td></tr>'}</tbody></table></div>`;}
function insights(d){if(!state.currentLoaded)return '';const title='기간별 주요 변동',scope=state.company==='전체'?'그룹 전체':state.company;if(!state.previousLoaded)return `<div class="insights"><h3>${title}</h3><p>${esc(scope)} 재직 인원은 <b>${fmt(d.s.count)}명</b>입니다. 비교일자 자료를 업로드하면 인원·평균연봉·연령·근속 구성의 변화를 표시합니다.</p></div>`;const early=(rows,asof)=>rows.filter(r=>P.years(r.join,asof)<3).length;const a=early(d.cur,state.date),b=early(d.prev,state.prevDate),hideEarly=state.suppress&&((a>0&&a<5)||(b>0&&b<5));const compare=(current,previous,unit,format=fmt)=>current==null||previous==null?'비교불가 (해당 정보 미입력)':`${format(previous)}${unit} → <b>${format(current)}${unit}</b> <span class="highlight-diff">(${current===previous?'변동 없음':signed(current-previous)+unit})</span>`;const salaryChange=d.s.average==null||d.p.average==null?'비교불가 (연봉 정보 미입력)':`${won(d.p.average)}만원 → <b>${won(d.s.average)}만원</b> <span class="highlight-diff">(${d.s.average===d.p.average?'변동 없음':signed(Math.round((d.s.average-d.p.average)/10000))+'만원'})</span>`;const earlyChange=hideEarly?'소규모 집단 보호 적용':`${fmt(b)}명 (${pct(b,d.prev.length)}) → <b>${fmt(a)}명 (${pct(a,d.cur.length)})</b>${d.prev.length&&d.cur.length?` <span class="highlight-diff">(${signed((a/d.cur.length-b/d.prev.length)*100)}%p)</span>`:''}`;const changes=P.changes(state.current,state.previous,state.date,state.prevDate,state.company);const items=[['재직 인원',compare(d.s.count,d.p.count,'명')],['평균연봉 · 입력자 기준',salaryChange],['평균연령 · 생년월일 입력자 기준',compare(d.s.age,d.p.age,'세')],['근속 3년 미만 구성',earlyChange]];const changedInfo=changes.changed.length?`계속 재직 중인 ${fmt(changes.changed.length)}명의 부서·직급·직군·고용형태·연봉 중 하나 이상이 변경되었습니다.`:'동일인으로 확인된 계속 재직자의 인사항목 변경은 없습니다.';return `<div class="insights period-highlights"><h3>${title}<small>${state.prevDate} → ${state.date}<br>${esc(scope)}</small></h3><div class="highlight-body"><div class="highlight-metrics">${items.map(([label,text])=>`<p><span class="highlight-label">${label}</span>${text}</p>`).join('')}</div><p class="highlight-note">${changedInfo} 회사별 증감의 ‘상세’에서 내역을 확인할 수 있습니다.${changes.unresolvedCurrent.length||changes.unresolvedPrevious.length?' 생년월일 누락·식별값 중복 인원은 동일인 확인이 필요합니다.':''} 평균연봉 변화에는 인력 구성 변화가 반영됩니다.</p></div></div>`;}
function jobGroups(rows,key){return [...new Set(rows.map(r=>r[key]||'미분류'))].map(label=>({label,count:rows.filter(r=>(r[key]||'미분류')===label).length})).sort((a,b)=>b.count-a.count||a.label.localeCompare(b.label,'ko'));}
function jobPanel(d,key,title){const known=d.cur.filter(r=>r[key]&&r[key]!=='미분류').length;return `<section class="panel">${head(title,'업로드 자료에 직접 입력된 분류 기준',`분류율 ${pct(known,d.cur.length)}`)}${bars(jobGroups(d.cur,key),d.cur.length)}<p class="reportnote">${known<d.cur.length?'비어 있는 항목은 미분류로 집계합니다. 부서명으로 자동 추정하지 않습니다.':'두 회사의 같은 업무 영역은 같은 직군명으로 분류합니다.'}</p></section>`;}
function structure(d){const types=jobGroups(d.cur,'type');return `${kpis(d)}<div class="grid">${tenurePanel(d)}${agePanel(d)}${genderPanel(d)}<section class="panel">${head('고용형태별 인원','입력된 고용형태 기준')}${bars(types,d.cur.length)}</section>${jobPanel(d,'family','직군별 인원현황')}${benchmarkPanel()}</div><section class="panel">${head('직급별 임금현황','재직자의 계약연봉 기준 · 평균 / 중앙값 / 연봉 비중','단위: 만원')}${rankTable(d)}<p class="reportnote">평균·중앙값·합계는 연봉 입력자만 집계합니다. 연봉이 비어 있는 사람은 임금통계에서 제외합니다.</p></section>`;}
function dataView(){return `<div class="uploadgrid">${['current','previous'].map((k,i)=>`<section class="panel">${head(i?'02. 이전 기준일 자료':'01. 보고 기준일 자료',i?'증감을 비교할 당시의 인사자료':'보고할 시점의 인사자료')}<label class="upload-date">${i?'비교일자':'작성일자'}<input type="date" id="${i?'previousDate':'currentDate'}" value="${i?state.prevDate:state.date}"><small>이 날짜를 기준으로 재직·연령·근속을 집계합니다.</small></label><div class="drop"><span style="font-size:28px;color:#087e7d">⇧</span><b>엑셀 또는 CSV 파일 선택</b><div class="mini">.xlsx / .xls / .csv · 여러 파일 선택 가능<br>두 회사 파일을 함께 선택하거나 한 파일로 통합하세요.</div><input type="file" id="${k}Upload" accept=".xlsx,.xls,.csv" multiple aria-label="${i?'이전':'현재'} 인사자료 업로드"></div><div class="filelabel">${esc(state[k+'File']||'등록된 자료 없음')}<br>${state[k+'Loaded']?state[k].length+'개 원본 행 · '+P.active(state[k],i?state.prevDate:state.date).length+'명 재직':'미등록'}</div></section>`).join('')}<section class="panel wide">${head('입력 양식 및 데이터 검증','첫 행에 아래 항목명을 사용하세요. 시트명으로도 회사를 구분할 수 있습니다.')}<div class="actions"><button id="template" class="button primary">↓ 엑셀 입력양식</button><button id="jobTemplate" class="button">↓ 직군 추가양식</button><button id="sampleDownload" class="button">↓ 예시자료 엑셀</button><button id="resetData" class="button">전체 자료 비우기</button></div><div class="tablewrap"><table><thead><tr><th>필수 입력</th><th>선택 입력</th><th>입력 기준</th></tr></thead><tbody><tr><td>회사명 · 이름 · 입사일</td><td>근무부서 · 직급 · 성별 · 생년월일<br>퇴사일 · 고용형태 · 연봉<br>직군 (추가양식 선택 시)</td><td>날짜 YYYY-MM-DD<br>연봉: 원 단위 숫자 (예: 50000000)</td></tr></tbody></table></div><p class="method">기본 양식은 <b>회사명, 이름, 근무부서, 직급, 성별, 생년월일, 입사일, 퇴사일, 고용형태, 연봉</b> 순서입니다. 회사명은 <b>플랜티넷 / 플랜티엠</b>으로 입력하세요. 사번은 필요하지 않습니다. 한 행을 한 명으로 집계하며, 이름이 같아도 다른 행이면 별도 인원으로 집계합니다. 엑셀의 ‘플랜티넷’, ‘플랜티엠’ 시트에 나눠 입력할 경우 회사명 열이 비어 있어도 시트명으로 구분합니다. 양식의 ‘작성안내’ 시트는 분석에서 제외됩니다.<br>자료를 다시 올리면 해당 기준일의 기존 자료를 교체합니다. 퇴사일은 재직하지 않는 첫날로 처리하며, 기준일보다 늦게 입사한 사람은 제외합니다. 연봉이 비어 있으면 0원으로 바꾸지 않고 임금통계에서 제외합니다. 오류가 있으면 전체 업로드를 취소하고 기존 자료를 유지합니다.</p>${state.warnings?`<div class="error" role="status">${esc(state.warnings)}</div>`:''}${state.error?`<div role="alert" class="error">${esc(state.error)}</div>`:''}</section><section class="panel wide">${head('직군 분류 가이드','두 회사에서 같은 업무는 같은 분류명을 사용하세요.')}<p class="method">인력 구성 보고는 <b>직군</b>으로 분류합니다. 직무를 별도로 입력할 필요는 없습니다. 동일 부서에도 서로 다른 직무가 있을 수 있으므로 <b>실제 주된 업무</b>를 기준으로 인사담당자가 확인해 입력합니다. 겸직자는 대표 직군 하나를 지정하여 중복 집계하지 않습니다.</p><div class="tablewrap"><table><thead><tr><th>직군 예시 (회사 기준 확정 전)</th><th>포함 업무 예시</th></tr></thead><tbody><tr><td>경영지원</td><td>인사 / 재무·회계 / 총무 / 법무</td></tr><tr><td>연구개발</td><td>백엔드 개발 / 프론트엔드 개발 / QA / 데이터 분석</td></tr><tr><td>기술운영</td><td>인프라 운영 / 보안 운영 / 기술지원</td></tr><tr><td>영업·사업</td><td>B2B 영업 / 사업개발 / 영업관리</td></tr><tr><td>기획·마케팅</td><td>서비스 기획 / 마케팅 / 디자인</td></tr><tr><td>고객서비스</td><td>고객상담 / 고객 운영</td></tr></tbody></table></div><p class="mini">위 분류는 제안 예시이며 실제 조직·직무에 맞춰 조정하세요. 임원은 직급으로 관리하며, 직군은 실제 담당 기능으로 입력합니다. 입력하지 않은 직군은 미분류로 표시합니다.</p></section><section class="panel wide">${head('집계 기준과 개인정보 보호','자료 처리 방식과 보고 시 유의할 내용')}<div class="method">• 기준일 인원 = 입사일 ≤ 기준일, 퇴사일이 없거나 퇴사일 > 기준일인 사람입니다.<br>• 인원 증감 = 이번 기준일 재직 인원 − 이전 기준일 자료의 재직 인원입니다. 자료에 없는 퇴사자는 추정하지 않습니다.<br>• 근속구간은 정확한 입사일 기념일 기준으로 구분합니다. 연령은 만 나이로 계산합니다.<br>• 연봉 합계는 계약연봉의 합입니다. 급여 실지급액·퇴직급여·보험료를 포함한 총 인건비는 별도 자료가 필요합니다.<br>• 파일은 이 페이지의 브라우저 메모리에서만 처리합니다. 새로고침 또는 페이지 종료 시 인사자료가 사라집니다. 다운로드한 보고서는 사용자 기기에 저장됩니다.<br>• 실명은 보고서에 표시하지 않습니다. 사번 없이 회사별 총인원 차이를 비교하며, 개인별 이동 이력은 추적하지 않습니다. PDF에는 개인별 원본자료를 포함하지 않습니다.<br>• 이전 기준일 자료의 직급·연봉은 당시 값으로 입력하세요. 현 자료만으로 과거 연봉을 복원하지 않습니다.</div><p><label class="mini"><input id="suppress" type="checkbox" ${state.suppress?'checked':''}> 5명 미만 집단 보호: 일부 상세 차트·직급 통계를 숨김 (전체 합계 및 증감은 유지되므로 완전한 비식별화를 보장하지 않음)</label></p></section></div>`;}
function welcomeMarkup(){return `<section class="panel welcome-panel"><span class="eyebrow">PLANTYNET GROUP / PEOPLE REPORT</span><h2>인사자료를 올리면<br>보고 내용이 완성됩니다.</h2><p>플랜티넷·플랜티엠의 인원, 근속, 연령, 직군과 임금현황을<br class="desktop-only"> 회사별·그룹 전체로 확인하세요.</p><div class="welcome-steps"><div><b>01</b><span>엑셀 입력양식 받기</span><small>회사명·이름·입사일 등 기초정보 입력</small></div><div><b>02</b><span>작성·비교 자료 올리기</span><small>두 시점의 자료로 변동 내역 비교</small></div><div><b>03</b><span>보고 내용 확인하기</span><small>요약·상세 분석·A4 PDF 출력</small></div></div><button id="startUpload" class="button primary">자료 업로드 시작 →</button><p class="welcome-privacy">인사자료는 각 방문자의 브라우저에서만 처리됩니다. 링크만 전달하면 업로드한 자료가 다른 사람에게 공유되지는 않습니다.</p></section>`;}
function dateBadges(){return `<span><small>작성일자</small><b>${state.date}</b></span><span><small>비교일자</small><b>${state.previousLoaded?state.prevDate:'자료 미등록'}</b></span>`;}
function overviewMarkup(d,forPdf=false){return `${kpis(d)}${insights(d)}<div class="grid">${companyPanel()}${tenurePanel(d)}</div>${forPdf?'':`<section class="panel overview-more">${head('상세 인력 구성과 임금현황','연령·성별·고용형태·직군과 직급별 연봉은 상세페이지에서 확인하세요.')}<button id="detailNav" class="button primary">인력구성 상세 보기 →</button></section>`}`;}
function render(){const labels={overview:['그룹 인원현황','OVERVIEW'],structure:['인력구성 상세','WORKFORCE'],data:['자료 업로드','DATA CENTER']};$('#pageTitle').textContent=labels[state.tab][0];$('#sectionLabel').textContent=labels[state.tab][1];document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===state.tab));document.querySelectorAll('[data-company]').forEach(b=>b.classList.toggle('selected',b.dataset.company===state.company));$('#notice').innerHTML=`<span>${state.demo?'DEMO':state.currentLoaded?'DATA':'READY'}</span>${state.demo?'가상 예시자료로 구성된 화면입니다. 실제 보고에는 인사자료를 업로드해 주세요.':state.currentLoaded?'업로드한 인사자료로 집계했습니다. 브라우저 종료 시 자료는 사라집니다.':'인사자료를 업로드하면 회사별 보고 내용을 자동 생성합니다.'}<button id="clear">자료 비우기</button>`;$('#clear').onclick=reset;$('#subtitle').textContent=state.tab==='data'?'인사자료를 보고 가능한 숫자로 바꿉니다.':`${state.company==='전체'?'그룹 전체':state.company} · 인력 현황 및 변화`;$('#reportDates').innerHTML=dateBadges();const d=data();$('#print').disabled=!state.currentLoaded;$('#view').innerHTML=state.tab==='data'?dataView():!state.currentLoaded?welcomeMarkup()+(state.tab==='structure'?benchmarkPanel():''):state.tab==='overview'?overviewMarkup(d):structure(d);if(!state.currentLoaded&&state.tab!=='data')$('#startUpload').onclick=()=>{state.tab='data';render();};if(state.currentLoaded&&state.tab==='overview')$('#detailNav').onclick=()=>{state.tab='structure';render();};document.querySelectorAll('[data-benchmark]').forEach(b=>b.onclick=()=>{state.benchmark=b.dataset.benchmark;render();});document.querySelectorAll('[data-change-company]').forEach(b=>b.onclick=()=>openChanges(b.dataset.changeCompany));document.querySelectorAll('#view .tablewrap').forEach(el=>{el.tabIndex=0;el.setAttribute('role','region');el.setAttribute('aria-label','표를 좌우로 스크롤하여 전체 내용을 확인하세요');el.insertAdjacentHTML('afterend','<p class="mobile-table-hint">표를 좌우로 밀어 전체 항목을 확인하세요.</p>');});if(state.tab==='data')bindData();}
function reset(){closeExport();state.current=[];state.previous=[];state.currentLoaded=false;state.previousLoaded=false;state.demo=false;state.currentFile='';state.previousFile='';state.error='';state.warnings='';render();toast('브라우저의 인사자료를 비웠습니다.');}
function downloadBook(sheets,name){const wb=XLSX.utils.book_new();sheets.forEach(([name,rows])=>{const ws=XLSX.utils.aoa_to_sheet(rows);ws['!cols']=(rows[0]||[]).map((_,i)=>({wch:i===0?22:19}));XLSX.utils.book_append_sheet(wb,ws,name);});const bytes=XLSX.write(wb,{bookType:'xlsx',type:'array'});presentDownload(new Blob([bytes],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'}),name,'엑셀 입력양식',false);}
function template(extended=false){downloadBook([['작성안내',[['플랜티넷 그룹 인사자료 작성안내'],['기본항목',P.headers.join(' / ')],['필수 입력','회사명 / 이름 / 입사일'],['회사명','플랜티넷 또는 플랜티엠 (해당 시트에서는 빈칸 가능)'],['날짜','YYYY-MM-DD 또는 엑셀 날짜'],['연봉','원 단위 숫자. 비어 있으면 임금통계 제외'],['퇴사일','재직하지 않는 첫날. 재직자는 빈칸'],['인원 집계','사번 없이 한 행을 한 명으로 집계. 중복 의심 행은 경고하며 자동 삭제하지 않음'],['직군','선택 입력. 실제 담당 업무의 큰 영역. 회사 공통 명칭 사용'],['직군 예시','경영지원 / 연구개발 / 기술운영 / 영업·사업 / 기획·마케팅 / 고객서비스'],['겸직 / 임원','겸직은 대표 직군 하나. 임원도 실제 담당 기능으로 분류'],['비교자료','이전 기준일 당시의 자료를 별도 파일로 작성'],['개인정보','이름은 보고서에 표시하지 않음. 서버 전송 없이 브라우저 내 집계']]],...P.companies.map(c=>[c,[extended?P.jobHeaders:P.headers]])],extended?'그룹_인사자료_직군_추가양식.xlsx':'그룹_인사자료_입력양식.xlsx');}
async function upload(files,key){if(!files.length)return;try{if(files.length>10)throw Error('한 번에 10개 이하의 파일을 선택하세요.');let records=[];for(const f of files){if(f.size>15*1024*1024)throw Error('파일은 개당 15MB 이하로 선택하세요.');const wb=XLSX.read(await f.arrayBuffer(),{type:'array',cellDates:true});let found=false;for(const name of wb.SheetNames){if(/안내|설명|readme/i.test(name))continue;const ws=wb.Sheets[name],raw=XLSX.utils.sheet_to_json(ws,{defval:''});if(!raw.length)continue;if(!Object.keys(raw[0]).some(k=>String(k).replace(/\s/g,'')==='입사일'))continue;found=true;raw.forEach((r,i)=>{if(P.companies.includes(name)&&!r['회사']&&!r['회사명'])r['회사명']=name;r.__source=`${f.name} / ${name} / ${i+2}행`;records.push(r);});}if(!found)throw Error(`${f.name}: 첫 행에 회사명·이름·입사일 등 항목명이 있는 시트가 필요합니다.`);}if(records.length>50000)throw Error('최대 50,000행까지 분석할 수 있습니다.');const result=P.normalize(records);if(result.errors.length)throw Error(result.errors.slice(0,25).join('\n')+(result.errors.length>25?`\n외 ${result.errors.length-25}개 오류`:''));if(state.demo){state.current=[];state.previous=[];state.currentLoaded=false;state.previousLoaded=false;state.currentFile='';state.previousFile='';state.demo=false;}state[key]=result.rows;state[key+'Loaded']=true;state[key+'File']=Array.from(files).map(f=>f.name).join(' · ');state.error='';state.warnings=result.warnings.slice(0,15).join('\n')+(result.warnings.length>15?`\n외 ${result.warnings.length-15}개 경고`:'');render();toast(`${key==='current'?'보고':'비교'} 자료 ${result.rows.length}행을 읽었습니다.`);}catch(e){state.error=e.message;render();toast('업로드를 취소했습니다. 오류 내용을 확인해 주세요.');}}
function bindData(){['currentDate','previousDate'].forEach(id=>$('#'+id).onchange=()=>{const a=$('#currentDate').value,b=$('#previousDate').value;if(!a||!b||b>=a){toast('비교일자는 작성일자보다 앞선 날짜로 입력하세요.');$('#currentDate').value=state.date;$('#previousDate').value=state.prevDate;return;}state.date=a;state.prevDate=b;render();});$('#currentUpload').onchange=e=>upload(Array.from(e.target.files),'current');$('#previousUpload').onchange=e=>upload(Array.from(e.target.files),'previous');$('#template').onclick=()=>template(false);$('#jobTemplate').onclick=()=>template(true);$('#sampleDownload').onclick=()=>{const saved=state;state={...state};sample();const rows=state.current;state=saved;downloadBook([['인사자료',[P.jobHeaders,...rows.map(x=>[x.company,x.name,x.department,x.rank,x.gender,x.birth,x.join,x.leave||'',x.type,x.salary,x.family])]]],'가상_인사자료_예시.xlsx');};$('#resetData').onclick=reset;$('#suppress').onchange=e=>{state.suppress=e.target.checked;render();};}
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{state.tab=b.dataset.tab;render();});document.querySelectorAll('[data-company]').forEach(b=>b.onclick=()=>{state.company=b.dataset.company;render();});$('#uploadNav').onclick=()=>{state.tab='data';render();};$('#print').onclick=openPrintReport;$('#shareSite').onclick=shareSite;render();
